    typeof r.hash === "string" && /^0x[0-9a-fA-F]{64}$/.test(r.hash) &&
    typeof r.method === "string" && typeof r.label === "string" &&
    typeof r.actor === "string" && typeof r.contract === "string" && typeof r.submittedAt === "number"
